import sys

def solve():
    try:
        input_data = sys.stdin.read().split()
        if not input_data:
            return
        X = int(input_data[0])
    except ValueError:
        return

    n = 1
    fact = 1

    # Since N! grows fast, we can just iterate.
    # We know N <= 20 for X <= 3*10^18.

    while fact < X:
        n += 1
        fact *= n

    if fact == X:
        print(n)
    else:
        # This part should theoretically not be reached given the problem statement guarantees
        # a solution exists.
        pass

if __name__ == '__main__':
    solve()
